create extension if not exists pgcrypto;
create table if not exists households(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table if not exists household_members(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade,user_id uuid not null,display_name text not null,role text default 'parent',created_at timestamptz default now(),unique(household_id,user_id));
create table if not exists tasks(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade,title text not null,description text,owner_user_id uuid,due_date date,category text,status text default 'open',recurrence text,created_at timestamptz default now());
create table if not exists meals(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade,meal_date date not null,meal text not null,notes text);
create table if not exists shopping_items(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade,item text not null,quantity numeric default 1,category text,source text,completed boolean default false);
create table if not exists pantry_items(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade,item text not null,quantity numeric default 0,minimum_quantity numeric default 0,category text,expiration date);
create table if not exists maintenance(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade,item text not null,next_due date,frequency text,owner_user_id uuid,notes text);
create table if not exists appointments(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade,family_member text not null,type text not null,appointment_date date,appointment_time time,provider text,questions text,follow_up_date date,notes text);
create table if not exists google_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null,household_id uuid references households(id) on delete cascade,google_email text,encrypted_refresh_token text not null,calendar_id text default 'primary',created_at timestamptz default now());
alter table households enable row level security; alter table household_members enable row level security; alter table tasks enable row level security; alter table meals enable row level security; alter table shopping_items enable row level security; alter table pantry_items enable row level security; alter table maintenance enable row level security; alter table appointments enable row level security; alter table google_connections enable row level security;
